import{z as A,x as d,o as r,c as B,q as n,j as l,D as E,d as o,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"随机化算法直觉","description":"","frontmatter":{"title":"随机化算法直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/randomized-algo.md","filePath":"cs/randomized-algo.md","lastUpdated":1791413859000}'),p={name:"cs/randomized-algo.md"};function C(h,a,m,D,c,f){const t=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=n('<h1 id="随机化算法直觉" tabindex="-1">随机化算法直觉 <a class="header-anchor" href="#随机化算法直觉" aria-label="Permalink to &quot;随机化算法直觉&quot;">​</a></h1><div class="epigraph"><p>硬币可以写进算法：Las Vegas 永远对、时间是随机变量；Monte Carlo 限时、以小概率错。</p><footer>—— 据 CLRS 第 5、7、34 章；Motwani and Raghavan, Randomized Algorithms, 1995 整理</footer></div><p>上一课<a href="/cs/approximation-ratio">近似比</a>的 \\(\\rho\\) 是确定性最坏倍数。<a href="/cs/quicksort-expected">快排与期望</a>已经用过算法内的硬币。本课不重做指示器求和。缺口是把随机化收成算法课的出口：两类错误、指纹与抽样、以及「期望多项式 / 高概率」与 NP 证书的关系。下一课起对象换回图：强连通分量把环捏成点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>确定性最坏可能平方或指数，随机打乱或随机轴把对手的输入洗成期望好。Las Vegas：输出总正确，如随机快排、随机选择；分析 \\(E[T]\\)。Monte Carlo：可能错，如指纹判相等（多项式哈希碰撞）、随机化 Miller–Rabin 一类数论测试——本课点名素性，不写数论证明。缺口是分类，不是再证快排。</p><p><span class="marginnote">术语翻译：Las Vegas 算法就像「宁可多花时间也绝不说错话」——它从不给错答案，只是运行时间随硬币浮动；Monte Carlo 算法则像「限时交卷，允许极小概率写错」——时间固定，正确性留一个小尾巴。选哪类取决于场景：数据库索引宁可 Las Vegas，实时风控可能只能 Monte Carlo。</span></p><p>近似也可以随机：期望比或高概率比。与上一课确定性 \\(\\rho\\) 并列，不要混成「差不多」。<span class="marginnote">常见误区：初学者容易把「期望运行时间 \\(O(n\\log n)\\)」当成「几乎每次都是这个量级」。实际上期望只是平均值——个别输入上可能远慢，只是慢的情形被硬币分布摊平了。要「几乎每次都快」，得另证高概率界（如 \\(O(n\\log n)\\) 的概率 \\(\\gt 1-1/n^c\\)）。</span>RP、BPP 是复杂度类名字，本课点到：多项式时间 Monte Carlo 一边错；不把 \\(P\\stackrel{?}{=}BPP\\) 当定理。</p><h3 id="期望不是平均输入" tabindex="-1">期望不是平均输入 <a class="header-anchor" href="#期望不是平均输入" aria-label="Permalink to &quot;期望不是平均输入&quot;">​</a></h3><p>上一课快排已强调：硬币在算法里，输入可以任意固定。本课沿用。平均情形分析（输入分布）是另一模型，不在主干。</p><p><span class="marginnote">Motwani–Raghavan 教材是随机算法标准书。CLRS 用指示器、随机增量、指纹。Karger 最小割等点名不展开。指纹与<a href="/cs/hash-function">散列</a>同一碰撞语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清：错在哪一侧（否实例被当成是，或反之）、重复独立试验如何把错误指数压下去。期望线性选择、随机快排作 Las Vegas 例；指纹作 Monte Carlo 例。推导用线性期望，不必浓度不等式全文。</p>',12)),(r(),l(i,null,{default:E(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20COIN%5B%22%E7%AE%97%E6%B3%95%E5%86%85%E7%A1%AC%E5%B8%81%22%5D%20--%3E%20LV%5B%22Las%20Vegas%EF%BC%9A%E6%80%BB%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20COIN%20--%3E%20MC%5B%22Monte%20Carlo%EF%BC%9A%E5%8F%AF%E9%94%99%22%5D%0A%20%20LV%20--%3E%20QT%5B%22%E9%9A%8F%E6%9C%BA%E5%BF%AB%E6%8E%92%20%2F%20%E9%80%89%E6%8B%A9%22%5D%0A%20%20MC%20--%3E%20FP%5B%22%E6%8C%87%E7%BA%B9%20%2F%20%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B%E8%BF%91%E4%BC%BC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/discrete-probability"},"离散概率"),o("已有期望线性。本课只把算法类型接上去。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"去随机化（条件期望、有限独立）可以把部分硬币拿掉，本课不写完。NPC 搜索没有已知的随机多项式精确算法；随机化不自动把 3-SAT 放进 P。编译课的哈希词法、布局随机化（ASLR）是后课系统，不是本课的图算法。",-1)),a[6]||(a[6]=e("p",null,"Monte Carlo 的错误可以用重复独立试验压下去：单次错误率 \\(p\\)，独立跑 \\(k\\) 次取「任一次答对就通过」（对一侧可重复的判定），错误变成约 \\(p\\) 的幂。",-1)),(r(),l(i,null,{default:E(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8D%95%E6%AC%A1%E8%AF%95%E9%AA%8C%E9%94%99%E8%AF%AF%E7%8E%87%20p%22%5D%20--%3E%20B%5B%22%E5%90%8C%E4%B8%80%E8%BE%93%E5%85%A5%E6%8D%A2%E6%96%B0%E7%A1%AC%E5%B8%81%E5%86%8D%E8%B7%91%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%8B%AC%E7%AB%8B%E9%87%8D%E5%A4%8D%20k%20%E6%AC%A1%22%5D%0A%20%20C%20--%3E%20D%7B%22%E5%88%A4%E5%AE%9A%E8%A7%84%E5%88%99%E6%80%8E%E4%B9%88%E5%AE%9A%22%7D%0A%20%20D%20--%3E%20E%5B%22%E4%BB%BB%E4%B8%80%E6%AC%A1%E7%AD%94%E5%AF%B9%E5%8D%B3%E6%8E%A5%E5%8F%97%22%5D%0A%20%20D%20--%3E%20F%5B%22k%20%E6%AC%A1%E5%85%A8%E9%94%99%E6%89%8D%E8%AF%AF%E5%88%A4%22%5D%0A%20%20F%20--%3E%20G%5B%22%E9%94%99%E8%AF%AF%E7%8E%87%E7%BA%A6%E7%AD%89%E4%BA%8E%20p%20%E7%9A%84%20k%20%E6%AC%A1%E5%B9%82%22%5D%0A%20%20G%20--%3E%20H%5B%22%E6%95%B0%E5%AD%97%E4%BE%8B%EF%BC%9Ap%3D10%25%EF%BC%8Ck%3D3%20%E2%86%92%20%E7%BA%A6%200.1%25%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：单次误判率 \\(p=10\\%\\) 听起来不低，但独立重复 \\(k=3\\) 次后误判率约 \\(0.1^3 = 0.1\\%\\)；\\(k=7\\) 就压到千万分之一。代价只是把运行时间乘 \\(k\\)——用线性代价换指数级可靠性，这是随机算法最划算的一笔交易。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Chernoff 全文，不引入 PCP。不把密码学原语当随机算法习题。算法栏到此：图、串、范式、难解、近似与硬币都已开口。后课默认：随机化要声明 Las Vegas 还是 Monte Carlo。下一课接回图——强连通分量，不再抛硬币。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Las Vegas 正确、时间随机；Monte Carlo 可错、可重复压错误。</li><li>硬币在算法内；不代替 NP 证书。</li><li>算法课收束；下一课从强连通分量开始。</li><li>出处：CLRS 第 5、7 章；Motwani and Raghavan, 1995。</li></ul>',5))])}const P=A(p,[["render",C]]);export{u as __pageData,P as default};
